CREATE TABLE IF NOT EXISTS "suppliers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Short supplier code used on paperwork and in EDI messages.
	"code" VARCHAR(24) NOT NULL UNIQUE,
	-- Legal or trading name.
	"name" VARCHAR(200) NOT NULL,
	-- Address purchase orders are sent to.
	"contact_email" VARCHAR(320),
	-- Typical days from order to receipt; feeds reorder calculations.
	"lead_time_days" INTEGER,
	-- False for suppliers no longer used. Kept so historical orders still resolve.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "suppliers" IS 'Who stock is bought from. Lead time lives here because reorder points are meaningless without it.';
COMMENT ON COLUMN "suppliers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "suppliers"."code" IS 'Short supplier code used on paperwork and in EDI messages.';
COMMENT ON COLUMN "suppliers"."name" IS 'Legal or trading name.';
COMMENT ON COLUMN "suppliers"."contact_email" IS 'Address purchase orders are sent to.';
COMMENT ON COLUMN "suppliers"."lead_time_days" IS 'Typical days from order to receipt; feeds reorder calculations.';
COMMENT ON COLUMN "suppliers"."is_active" IS 'False for suppliers no longer used. Kept so historical orders still resolve.';

CREATE TABLE IF NOT EXISTS "warehouses" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Short site code, e.g. LON1.
	"code" VARCHAR(16) NOT NULL UNIQUE,
	-- Site name.
	"name" VARCHAR(120) NOT NULL,
	-- Street address for carriers.
	"address_line1" VARCHAR(200),
	-- City or locality.
	"city" VARCHAR(120),
	-- ISO 3166-1 alpha-2 country code, needed for customs paperwork.
	"country_code" CHAR(2) NOT NULL,
	-- IANA zone. Cut-off times and shift reports are local, timestamps are UTC.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- False when a site is closed but its history is retained.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "warehouses" IS 'A physical site. Everything below is scoped to a warehouse, because the same SKU in two buildings is two independent pools of stock.';
COMMENT ON COLUMN "warehouses"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "warehouses"."code" IS 'Short site code, e.g. LON1.';
COMMENT ON COLUMN "warehouses"."name" IS 'Site name.';
COMMENT ON COLUMN "warehouses"."address_line1" IS 'Street address for carriers.';
COMMENT ON COLUMN "warehouses"."city" IS 'City or locality.';
COMMENT ON COLUMN "warehouses"."country_code" IS 'ISO 3166-1 alpha-2 country code, needed for customs paperwork.';
COMMENT ON COLUMN "warehouses"."timezone" IS 'IANA zone. Cut-off times and shift reports are local, timestamps are UTC.';
COMMENT ON COLUMN "warehouses"."is_active" IS 'False when a site is closed but its history is retained.';

CREATE TABLE IF NOT EXISTS "storage_locations" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Site the location belongs to.
	"warehouse_id" BIGINT NOT NULL,
	-- Bin label as printed, e.g. A-12-3. Unique within the warehouse, not globally.
	"code" VARCHAR(32) NOT NULL,
	-- bin | bulk | staging | receiving | quarantine. Quarantine holds stock that must not be sold.
	"location_type" VARCHAR(24) NOT NULL DEFAULT 'bin',
	-- Pick zone, used to batch and route pickers.
	"zone" VARCHAR(24),
	-- Soft capacity in units, used by put-away suggestions.
	"capacity_units" INTEGER,
	-- False for receiving and quarantine, so pick logic skips them.
	"is_pickable" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "storage_locations" IS 'A bin. Tracking stock to the bin rather than the building is what makes a pick list walkable and a cycle count meaningful.';
COMMENT ON COLUMN "storage_locations"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "storage_locations"."warehouse_id" IS 'Site the location belongs to.';
COMMENT ON COLUMN "storage_locations"."code" IS 'Bin label as printed, e.g. A-12-3. Unique within the warehouse, not globally.';
COMMENT ON COLUMN "storage_locations"."location_type" IS 'bin | bulk | staging | receiving | quarantine. Quarantine holds stock that must not be sold.';
COMMENT ON COLUMN "storage_locations"."zone" IS 'Pick zone, used to batch and route pickers.';
COMMENT ON COLUMN "storage_locations"."capacity_units" IS 'Soft capacity in units, used by put-away suggestions.';
COMMENT ON COLUMN "storage_locations"."is_pickable" IS 'False for receiving and quarantine, so pick logic skips them.';

CREATE UNIQUE INDEX "uq_locations_warehouse_code"
ON "storage_locations" ("warehouse_id", "code");
CREATE INDEX "idx_locations_warehouse_zone"
ON "storage_locations" ("warehouse_id", "zone");

CREATE TABLE IF NOT EXISTS "items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stock keeping unit. The identifier every other system agrees on.
	"sku" VARCHAR(64) NOT NULL UNIQUE,
	-- Description printed on pick lists and packing slips.
	"name" VARCHAR(200) NOT NULL,
	-- GTIN or EAN scanned at receipt and pick.
	"barcode" VARCHAR(64) UNIQUE,
	-- each | kg | litre | case. Quantities are meaningless without it.
	"unit_of_measure" VARCHAR(16) NOT NULL DEFAULT 'each',
	-- Unit weight, used for shipping rates and pallet planning.
	"weight_grams" INTEGER,
	-- True for food, pharma and anything with an expiry; forces a lot on every movement.
	"is_lot_tracked" BOOLEAN NOT NULL DEFAULT false,
	-- False when discontinued. Existing stock and history stay.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "items" IS 'The stocked article. One row per SKU, not per physical unit — quantities live in stock_levels and history in stock_movements.';
COMMENT ON COLUMN "items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "items"."sku" IS 'Stock keeping unit. The identifier every other system agrees on.';
COMMENT ON COLUMN "items"."name" IS 'Description printed on pick lists and packing slips.';
COMMENT ON COLUMN "items"."barcode" IS 'GTIN or EAN scanned at receipt and pick.';
COMMENT ON COLUMN "items"."unit_of_measure" IS 'each | kg | litre | case. Quantities are meaningless without it.';
COMMENT ON COLUMN "items"."weight_grams" IS 'Unit weight, used for shipping rates and pallet planning.';
COMMENT ON COLUMN "items"."is_lot_tracked" IS 'True for food, pharma and anything with an expiry; forces a lot on every movement.';
COMMENT ON COLUMN "items"."is_active" IS 'False when discontinued. Existing stock and history stay.';

CREATE TABLE IF NOT EXISTS "lots" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Item this lot is of.
	"item_id" BIGINT NOT NULL,
	-- Manufacturer batch or lot number as printed on the carton.
	"lot_code" VARCHAR(64) NOT NULL,
	-- Expiry date. Drives FEFO picking and blocks shipment of expired stock.
	"expires_on" DATE,
	-- First receipt date for this lot, used for FIFO when there is no expiry.
	"received_on" DATE,
	-- Supplier the lot came from, needed for a recall.
	"supplier_id" BIGINT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "lots" IS 'A batch of a lot-tracked item. Recalls are the reason this exists: given a lot code, the movement log gives you every location and every customer it reached.';
COMMENT ON COLUMN "lots"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "lots"."item_id" IS 'Item this lot is of.';
COMMENT ON COLUMN "lots"."lot_code" IS 'Manufacturer batch or lot number as printed on the carton.';
COMMENT ON COLUMN "lots"."expires_on" IS 'Expiry date. Drives FEFO picking and blocks shipment of expired stock.';
COMMENT ON COLUMN "lots"."received_on" IS 'First receipt date for this lot, used for FIFO when there is no expiry.';
COMMENT ON COLUMN "lots"."supplier_id" IS 'Supplier the lot came from, needed for a recall.';

CREATE UNIQUE INDEX "uq_lots_item_code"
ON "lots" ("item_id", "lot_code");
CREATE INDEX "idx_lots_expiry"
ON "lots" ("expires_on");

CREATE TABLE IF NOT EXISTS "stock_levels" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Site holding the stock.
	"warehouse_id" BIGINT NOT NULL,
	-- Bin holding the stock.
	"location_id" BIGINT NOT NULL,
	-- Item held.
	"item_id" BIGINT NOT NULL,
	-- Lot held. Null for items that are not lot tracked.
	"lot_id" BIGINT,
	-- Units physically present in this bin.
	"quantity_on_hand" INTEGER NOT NULL DEFAULT 0,
	-- Units promised to open shipments but not yet picked. Available is on_hand minus allocated.
	"quantity_allocated" INTEGER NOT NULL DEFAULT 0,
	-- Last cycle count. Drives count scheduling and variance reporting.
	"last_counted_at" TIMESTAMP,
	-- Last movement affecting this row.
	"updated_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "stock_levels" IS 'Current quantity per bin, item and lot. It is a materialised view of the movement log, maintained transactionally, and any disagreement is resolved in favour of the movements.';
COMMENT ON COLUMN "stock_levels"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "stock_levels"."warehouse_id" IS 'Site holding the stock.';
COMMENT ON COLUMN "stock_levels"."location_id" IS 'Bin holding the stock.';
COMMENT ON COLUMN "stock_levels"."item_id" IS 'Item held.';
COMMENT ON COLUMN "stock_levels"."lot_id" IS 'Lot held. Null for items that are not lot tracked.';
COMMENT ON COLUMN "stock_levels"."quantity_on_hand" IS 'Units physically present in this bin.';
COMMENT ON COLUMN "stock_levels"."quantity_allocated" IS 'Units promised to open shipments but not yet picked. Available is on_hand minus allocated.';
COMMENT ON COLUMN "stock_levels"."last_counted_at" IS 'Last cycle count. Drives count scheduling and variance reporting.';
COMMENT ON COLUMN "stock_levels"."updated_at" IS 'Last movement affecting this row.';

CREATE UNIQUE INDEX "uq_stock_location_item_lot"
ON "stock_levels" ("location_id", "item_id", "lot_id");
CREATE INDEX "idx_stock_warehouse_item"
ON "stock_levels" ("warehouse_id", "item_id");

CREATE TABLE IF NOT EXISTS "stock_movements" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Site where the movement happened.
	"warehouse_id" BIGINT NOT NULL,
	-- Item moved.
	"item_id" BIGINT NOT NULL,
	-- Lot moved, for lot-tracked items.
	"lot_id" BIGINT,
	-- Source bin. Null for a receipt, where stock enters from outside.
	"from_location_id" BIGINT,
	-- Destination bin. Null for a shipment or a write-off, where stock leaves.
	"to_location_id" BIGINT,
	-- Units moved. Always positive; direction is expressed by the two location columns.
	"quantity" INTEGER NOT NULL,
	-- receipt | putaway | transfer | pick | ship | adjustment | return | scrap.
	"movement_type" VARCHAR(24) NOT NULL,
	-- Document class that caused the movement, e.g. purchase_order or shipment.
	"reference_type" VARCHAR(24),
	-- Identifier of that document, kept loose so one log can serve every document type.
	"reference_id" BIGINT,
	-- Operator or system that made the movement.
	"performed_by" VARCHAR(80),
	-- When it happened. Rows are append-only; a mistake is corrected by a compensating movement.
	"occurred_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "stock_movements" IS 'The append-only truth. Every change to stock is a row here; stock_levels is derived from it. This is what makes a variance explainable and a recall traceable.';
COMMENT ON COLUMN "stock_movements"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "stock_movements"."warehouse_id" IS 'Site where the movement happened.';
COMMENT ON COLUMN "stock_movements"."item_id" IS 'Item moved.';
COMMENT ON COLUMN "stock_movements"."lot_id" IS 'Lot moved, for lot-tracked items.';
COMMENT ON COLUMN "stock_movements"."from_location_id" IS 'Source bin. Null for a receipt, where stock enters from outside.';
COMMENT ON COLUMN "stock_movements"."to_location_id" IS 'Destination bin. Null for a shipment or a write-off, where stock leaves.';
COMMENT ON COLUMN "stock_movements"."quantity" IS 'Units moved. Always positive; direction is expressed by the two location columns.';
COMMENT ON COLUMN "stock_movements"."movement_type" IS 'receipt | putaway | transfer | pick | ship | adjustment | return | scrap.';
COMMENT ON COLUMN "stock_movements"."reference_type" IS 'Document class that caused the movement, e.g. purchase_order or shipment.';
COMMENT ON COLUMN "stock_movements"."reference_id" IS 'Identifier of that document, kept loose so one log can serve every document type.';
COMMENT ON COLUMN "stock_movements"."performed_by" IS 'Operator or system that made the movement.';
COMMENT ON COLUMN "stock_movements"."occurred_at" IS 'When it happened. Rows are append-only; a mistake is corrected by a compensating movement.';

CREATE INDEX "idx_movements_item_time"
ON "stock_movements" ("item_id", "occurred_at");
CREATE INDEX "idx_movements_warehouse_time"
ON "stock_movements" ("warehouse_id", "occurred_at");
CREATE INDEX "idx_movements_reference"
ON "stock_movements" ("reference_type", "reference_id");

CREATE TABLE IF NOT EXISTS "purchase_orders" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Supplier ordered from.
	"supplier_id" BIGINT NOT NULL,
	-- Site the goods are delivered to.
	"warehouse_id" BIGINT NOT NULL,
	-- Reference quoted to the supplier and on the delivery note.
	"order_number" VARCHAR(32) NOT NULL UNIQUE,
	-- draft | sent | partially_received | received | cancelled.
	"status" VARCHAR(24) NOT NULL DEFAULT 'draft',
	-- When the order was sent.
	"ordered_at" TIMESTAMP,
	-- Expected delivery date, from supplier lead time.
	"expected_on" DATE,
	-- When the last line was received.
	"received_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "purchase_orders" IS 'An inbound order. Receiving against a purchase order is what lets short and over deliveries be measured rather than silently absorbed.';
COMMENT ON COLUMN "purchase_orders"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "purchase_orders"."supplier_id" IS 'Supplier ordered from.';
COMMENT ON COLUMN "purchase_orders"."warehouse_id" IS 'Site the goods are delivered to.';
COMMENT ON COLUMN "purchase_orders"."order_number" IS 'Reference quoted to the supplier and on the delivery note.';
COMMENT ON COLUMN "purchase_orders"."status" IS 'draft | sent | partially_received | received | cancelled.';
COMMENT ON COLUMN "purchase_orders"."ordered_at" IS 'When the order was sent.';
COMMENT ON COLUMN "purchase_orders"."expected_on" IS 'Expected delivery date, from supplier lead time.';
COMMENT ON COLUMN "purchase_orders"."received_at" IS 'When the last line was received.';

CREATE INDEX "idx_po_supplier_status"
ON "purchase_orders" ("supplier_id", "status");

CREATE TABLE IF NOT EXISTS "purchase_order_lines" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent order.
	"purchase_order_id" BIGINT NOT NULL,
	-- Item ordered.
	"item_id" BIGINT NOT NULL,
	-- Units ordered.
	"quantity_ordered" INTEGER NOT NULL,
	-- Units received so far. Partial receipts are normal, so this is a running total.
	"quantity_received" INTEGER NOT NULL DEFAULT 0,
	-- Agreed unit cost in minor units, snapshotted at order time.
	"unit_cost_minor" BIGINT NOT NULL,
	-- Currency of unit_cost_minor.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "purchase_order_lines" IS 'Ordered versus received per item. The gap between the two columns is the supplier performance metric everyone eventually asks for.';
COMMENT ON COLUMN "purchase_order_lines"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "purchase_order_lines"."purchase_order_id" IS 'Parent order.';
COMMENT ON COLUMN "purchase_order_lines"."item_id" IS 'Item ordered.';
COMMENT ON COLUMN "purchase_order_lines"."quantity_ordered" IS 'Units ordered.';
COMMENT ON COLUMN "purchase_order_lines"."quantity_received" IS 'Units received so far. Partial receipts are normal, so this is a running total.';
COMMENT ON COLUMN "purchase_order_lines"."unit_cost_minor" IS 'Agreed unit cost in minor units, snapshotted at order time.';
COMMENT ON COLUMN "purchase_order_lines"."currency_code" IS 'Currency of unit_cost_minor.';

CREATE INDEX "idx_po_lines_order_item"
ON "purchase_order_lines" ("purchase_order_id", "item_id");

CREATE TABLE IF NOT EXISTS "shipments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Site shipping the goods.
	"warehouse_id" BIGINT NOT NULL,
	-- Reference printed on the packing slip.
	"shipment_number" VARCHAR(32) NOT NULL UNIQUE,
	-- Order id from the upstream commerce or ERP system.
	"external_order_reference" VARCHAR(64),
	-- Carrier used.
	"carrier" VARCHAR(60),
	-- Carrier tracking number once assigned.
	"tracking_number" VARCHAR(80),
	-- pending | allocated | picking | packed | shipped | cancelled.
	"status" VARCHAR(24) NOT NULL DEFAULT 'pending',
	-- Recipient name, snapshotted at allocation.
	"ship_to_name" VARCHAR(160) NOT NULL,
	-- Delivery address snapshot, so a later address edit cannot rewrite where a parcel went.
	"ship_to_address" JSON NOT NULL,
	-- Handover to the carrier.
	"shipped_at" TIMESTAMP,
	-- When the shipment was created.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "shipments" IS 'An outbound parcel. The warehouse does not need the customer record — a snapshot of where it goes is enough, and it keeps the two systems decoupled.';
COMMENT ON COLUMN "shipments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "shipments"."warehouse_id" IS 'Site shipping the goods.';
COMMENT ON COLUMN "shipments"."shipment_number" IS 'Reference printed on the packing slip.';
COMMENT ON COLUMN "shipments"."external_order_reference" IS 'Order id from the upstream commerce or ERP system.';
COMMENT ON COLUMN "shipments"."carrier" IS 'Carrier used.';
COMMENT ON COLUMN "shipments"."tracking_number" IS 'Carrier tracking number once assigned.';
COMMENT ON COLUMN "shipments"."status" IS 'pending | allocated | picking | packed | shipped | cancelled.';
COMMENT ON COLUMN "shipments"."ship_to_name" IS 'Recipient name, snapshotted at allocation.';
COMMENT ON COLUMN "shipments"."ship_to_address" IS 'Delivery address snapshot, so a later address edit cannot rewrite where a parcel went.';
COMMENT ON COLUMN "shipments"."shipped_at" IS 'Handover to the carrier.';
COMMENT ON COLUMN "shipments"."created_at" IS 'When the shipment was created.';

CREATE INDEX "idx_shipments_warehouse_status"
ON "shipments" ("warehouse_id", "status");

CREATE TABLE IF NOT EXISTS "shipment_lines" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent shipment.
	"shipment_id" BIGINT NOT NULL,
	-- Item to ship.
	"item_id" BIGINT NOT NULL,
	-- Lot picked, recorded at pick time for traceability.
	"lot_id" BIGINT,
	-- Units the order asked for.
	"quantity_requested" INTEGER NOT NULL,
	-- Units actually picked. A short pick leaves these different and triggers a back order.
	"quantity_picked" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "shipment_lines" IS 'Requested versus picked per item. Recording the lot at pick time is what turns a recall into a query instead of a phone call to every customer.';
COMMENT ON COLUMN "shipment_lines"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "shipment_lines"."shipment_id" IS 'Parent shipment.';
COMMENT ON COLUMN "shipment_lines"."item_id" IS 'Item to ship.';
COMMENT ON COLUMN "shipment_lines"."lot_id" IS 'Lot picked, recorded at pick time for traceability.';
COMMENT ON COLUMN "shipment_lines"."quantity_requested" IS 'Units the order asked for.';
COMMENT ON COLUMN "shipment_lines"."quantity_picked" IS 'Units actually picked. A short pick leaves these different and triggers a back order.';

CREATE INDEX "idx_shipment_lines_shipment_item"
ON "shipment_lines" ("shipment_id", "item_id");

